class Counter {
  int count = 0;

  void increment() {
    count++;
  }

  void reset() {
    count = 0;
  }

  void show() {
    print('Count: $count');
  }
}

void main() {
  Counter c = Counter();
  c.increment();
  c.increment();
  c.show(); // Count: 2
  c.reset();
  c.show(); // Count: 0
}
